from build import put,render
put('vln_trans',title='VLN-Trans: Translator for the Vision and Language Navigation Agent',authors=['Yue Zhang','Parisa Kordjamshidi'],year=2023,venue='ACL 2023, main long papers',pages=list(range(1,16)),
problem='The task is graph-based R2R/R4R navigation from a full instruction and panoramic observations. The motivating mismatch is specific: an instructor may name a landmark the visual encoder cannot recognize, or name a category shared by multiple candidate views. The output is a next-viewpoint distribution including STOP; the method assumes access to the current candidate views and offline navigation trajectories. It is not an online general-purpose LLM paraphraser.',
method='SyFiS constructs step-level motion-plus-landmark sentences from R2R and PREVALENT trajectories. Relative heading/elevation chooses one of six motion classes; CLIP ranks a fixed label vocabulary, and a target-exclusive recognized label supplies a positive landmark. Irrelevant labels give easy negatives and shared labels give hard negatives (§3.2). This uniqueness is relative to CLIP detections, not a verified property of the scene.\n\nSeparate text and visual LSTMs feed cross-modal soft attention. Its hidden vectors provide translated representations. Pretraining combines token-generation CE (SG) with a margin-based triplet objective (DSL). At navigation time an additional MLP predicts per-token relevance weights; the recurrent VLN-BERT text input concatenates original, translated, and relevance-weighted original features (§3.3–3.4, Eqs4–11). The actual output used by the navigator is latent representation, not a rewritten natural-language string (§6).\n\nTraining combines supervised expert action loss and sampled RL, plus SG and sub-instruction-split supervision where aligned FG-R2R/SyFiS data exist. Eq9 is a schematic and incomplete RL notation; a reward/advantage estimator is needed to operationalize it. Eq10 prints only a positive BCE term, so released code must establish the actual binary objective. ResNet-152 visual features, BERT language initialization, AdamW, translator batch16/lr1e−5 and navigation 300k iterations are specified (§4.2). Navigation pretraining additionally uses RxR and Marky-mT5. Inference is greedy recurrent viewpoint selection. Paper reports approximately two days for base pretraining on four RTX2080s and one day for fine-tuning on one unspecified RTX GPU; these are author timings.',
novelty='Relative to Speaker-Follower, the generated supervision is local and discriminative across candidates rather than a whole-route caption. Relative to FG-R2R and ADAPT, SyFiS explicitly chooses a recognizable candidate-exclusive landmark. The online translator is trained latent conditioning, so a frozen-LLM textual rewriting baseline tests a related but different mechanism. Data and architecture must be separated: Table1 includes base VLN-BERT, added RxR/Marky data, further SyFiS data, and translator variants.',
results='PAPER EXPERIMENT: Table1/PDF p7 improves unseen-validation SR from .63 for the original base to .65 with extra data, .67 with SyFiS, and .69 with FG-R2R-trained VLN-Trans. The data-matched ++ baseline has SPL .61 versus .63 for the full method. Test SR is .63 for the ++ baseline versus .66 for the full method. Table4/p8 gives the more controlled comparison: full alignment objectives reach .690 SR/.633 SPL versus .672/.611 for ++. These support a contribution beyond extra data in that experiment, but not a six-point pure architectural gain.\n\nTable4 also shows sub-instruction split supervision hurting R2R-Last (.503→.484 SR), where only one instruction sentence exists. R4R Table2 reports .46 SR/.25 sDTW versus reproduced VLN-BERT .43/.21. Quality assessment uses only 50 generated instructions and yields 58% human success; it is not a guarantee of semantic faithfulness. Figures4 and7/p9,13 document wrong landmark associations driven by training frequencies (kitchen–oven/cabinet, hall–pillar). The explicit limitations acknowledge latent interpretability and simulated-only evaluation. Verdict: useful local grounding and supervision, but the translator can substitute a statistically related object without preserving the user’s intended referent.',
findings=[{'claim':'The online translator contributes latent sub-instruction representations rather than an actual rewritten instruction.','evidence_type':'AUTHOR CLAIM','source':'VLN-Trans supplied PDF','locator':'§3.4 and §6, PDF pp6,9'},{'claim':'Extra navigation pretraining data already improve the baseline, and Table4 provides a data-matched ++ control.','evidence_type':'PAPER EXPERIMENT','source':'VLN-Trans supplied PDF','locator':'Tables1 and4, PDF pp7–8'}],
bottlenecks=[{'id':'vln_trans-B1','description':'A recognizable substitute landmark can be the wrong referent.','conditions':'Several plausible objects share a semantic association with the named room or object.','cause':'Offline co-occurrence and detector-defined uniqueness replace verified instruction-to-instance equivalence.','evidence':'Author failure cases in Figures4(c) and7(d,e), PDF pp9,13; §6 latent interpretability limitation.','kind':'methodological','followups':'GELA adds explicit entity grounding; SkillNav uses textual rewrites for routing. Neither comparison here establishes faithful online referent substitution.','status':'Partially addressed','confidence':'High for the documented failure mechanism; prevalence not measured.'}],limits=['No benchmark executed. Equation typography is treated as schematic until code verification.'])
put('gela',title='Grounded Entity-Landmark Adaptive Pre-training for Vision-and-Language Navigation',authors=['Yibo Cui','Liang Xie','Yakun Zhang','Meishan Zhang','Ye Yan','Erwei Yin'],year=2023,venue='ICCV 2023',pages=list(range(1,12)),
problem='GELA targets the absence of direct phrase-to-landmark supervision in graph VLN. It assumes panoramic RGB features, navigation history, a full instruction/dialogue, and human annotations during training. At inference it predicts next graph node or STOP. Its adaptive pretraining is an offline stage, not test-time adaptation.',
method='GEL-R2R annotates 71,467 entity phrases and 150,183 panoramic landmark boxes over R2R train/validation splits (Table1). Training uses only the training annotations; the validation annotations support analysis. Annotators follow free-phrase, coreference, alignment, and unique-landmark rules, with expert revision (§3).\n\nThe HAMT/LXMERT-derived transformer has text, current 36-view panorama and history encoders, followed by cross-modal attention. Instruction outputs are token vectors Z, view outputs S have 37 entries including STOP, and hidden width is768. EPP pools marked landmark views and predicts a distribution over the L+1 text positions. LBP pools marked phrase tokens and regresses a normalized4D box with smooth-L1 plus generalized-IoU loss. ELSA is symmetric multi-positive contrastive alignment over matching visual/text tokens, with temperature .07 (§4.3, Eqs1–8). The printed pooling products depend on the masks’ normalization; a binary mask would sum rather than average.\n\nAdaptive pretraining retains MLM, MRC, ITM, SAP and spatial-relation proxy tasks to avoid forgetting; augmented data without boxes contribute only those original tasks. New loss weights and box GIoU weight are1. Pretraining uses200k iterations, batch64 per GPU, lr5e−5, two3090s. Fine-tuning uses IL plus RL for100k iterations at1e−5, batch16 R2R/batch8 CVDN (§5.1). R2R experiments separately include no visual augmentation, style transfer, or semantic-mask image synthesis. Inference uses the pretrained navigation transformer without annotation access or an online phrase-grounding oracle.',
novelty='The important addition over FG-R2R and Landmark-RxR is entity-to-region human supervision inside sub-instructions, not just temporal sentence-to-subtrajectory alignment. The objectives adapt phrase-grounding ideas from MDETR/TransVG to panoramic HAMT representations. This is a combination of a new annotation resource and grounded auxiliary pretraining; it is not a new large foundation backbone.',
results='PAPER EXPERIMENT: Table2/p6 gives no-augmentation HAMT SR65.7/SPL60.9 versus GELA69.2/63.4 on R2R unseen validation. With semantic-mask visual augmentation GELA reaches71.1/65.0; attributing that whole result to entity alignment alone would conflate augmentation. Table5/p8 shows EPP alone65.8 SR and LBP alone65.6, ELSA66.3, EPP+LBP67.0, all three69.2. This is evidence of complementary objectives; it does not show every auxiliary is individually beneficial. CVDN test goal progress rises5.58→5.87m (Table4), a different metric from success.\n\nFigure3’s effective-attention score increases on annotated pairs. DEDUCTION: an attention-alignment diagnostic does not establish that the correct grounded entity causally determines a navigation action; a controlled landmark intervention would be stronger. Authors acknowledge costly limited annotation (§5.5). Their object-only/scene-only comparison also changes available data volume, explicitly acknowledged, so it cannot cleanly rank semantic category importance. Verdict: a concrete supervision resource and modest controlled gains; robustness under misleading, missing or repeated landmarks is not established.',
findings=[{'claim':'GELA is offline entity-grounding adaptive pretraining on HAMT, not online test-time adaptation.','evidence_type':'AUTHOR CLAIM','source':'GELA supplied PDF','locator':'§4, PDF pp4–6'},{'claim':'EPP and LBP alone do not improve the R2R baseline in Table5, whereas their combination with ELSA does.','evidence_type':'PAPER EXPERIMENT','source':'GELA supplied PDF','locator':'Table5, PDF p8'}],
bottlenecks=[{'id':'gela-B1','description':'High-quality entity grounding requires costly human boxes and does not certify decision-level language use.','conditions':'New domains, unseen landmark types, or ambiguous repeated objects beyond the annotated R2R scenes.','cause':'Limited human labels and proxy losses align representations without directly testing counterfactual action dependence.','evidence':'§5.5 acknowledges limited annotation; Figure3 measures attention rather than interventional behavior.','kind':'methodological','followups':'NavNuances tests atomic instruction interventions; synthetic-data methods reduce annotation cost but require correctness controls.','status':'Partially addressed','confidence':'High for annotation cost; medium for the untested decision-level limitation.'}],limits=['No benchmark executed. A separate official supplementary PDF is being located; main-paper coverage alone is not supplementary review.'])
put('navnuances',title='Navigating the Nuances: A Fine-grained Evaluation of Vision-Language Navigation',authors=['Zehao Wang','Minye Wu','Yixin Cao','Yubo Ma','Meiqi Chen','Tinne Tuytelaars'],year=2024,venue='Findings of EMNLP 2024',pages=list(range(1,25)),
problem='Standard endpoint SR and broad path metrics can hide failures to obey individual direction, ordinal, landmark or region concepts. NavNuances is an evaluation dataset and protocol, not a new trained navigation architecture. Its environment is the static Matterport3D navigation graph, with model-specific input/action interfaces preserved. Some diagnostic scenes overlap environments used by existing training sets; it tests atomic concepts rather than a uniformly unseen-scene generalization protocol.',
method='A context-free grammar is iteratively expanded with GPT-4 parsing and manual corrections, then used to construct five categories. Candidate paths come from graph geometry and Habitat semantic annotations; humans reject ambiguous starts and provide/check trajectories; GPT-4 enriches linguistic wording (§3, appendicesD–I). Counts are579 direction,170 vertical,78 numerical,275 region and685 landmark instances. There is no new learned loss. NavGPT4v adds directly indexed panoramic images to NavGPT’s text/history prompt.\n\nMetrics differ by category and must not be called ordinary R2R SR. Direction success considers the first movement in a120-degree left/right/back sector. Moving towards a landmark only requires ending closer to its center; walking past requires a geometric projection on the start–end segment plus final distance within3m. Numerical success requires both endpoint proximity and nDTW closer to the correct route than competing same-start ordinal routes. Region entry requires stopping inside an adjacent matching region; exit means outside the starting region. Vertical success is endpoint proximity (AppendixB). Dual SR requires both paired left/right commands to succeed from one starting view, directly exposing input insensitivity.\n\nThe random baseline takes five graph moves. Two extra ordinal controls know room layout, or layout plus side, but not ordinal semantics. This isolates more of the counting requirement than a uniform random walk. Expensive GPT-4 variants are evaluated on a random subset of roughly130 examples (§4.3), and prompts supply explicit bearings and candidate IDs. Human and model action interfaces differ, limiting simple architecture attribution.',
novelty='Relative to general instruction perturbation tests, this contribution uses semantically grounded, category-specific success definitions and paired contrasts. It is direct prior art for left/right counterfactual evaluation and ordinal route discrimination. It does not establish a universal causal measure of language reliance: candidate geometry, visual encoders, pretraining and action interfaces differ across models.',
results='PAPER EXPERIMENT: Table2/p6 shows DUET R2R SR71.52 but direction64.76, numerical26.92 and landmark35.76. ScaleVLN raises R2R SR to80.97 while numerical stays26.92 and landmark is29.92. This is a diagnostic association, not proof that synthetic scaling causes instruction neglect: the compared models and training recipes are not a randomized data intervention. NavGPT4v’s subset results are92.68 direction,39.13 numerical,62.87 landmark,56.25 region and13.64 vertical; its R2R SR41.30 illustrates task-specific strengths/tradeoffs.\n\nThe ordinal-aware random controls score32.06 (layout) and41.03 (layout+side), exceeding several trained agents; this makes their claimed numerical ability weaker than raw SR suggests (§4.4/Fig4). ScaleVLN’s right-turn SR exceeds left by18.23points (§4.4/p9); paired Dual SR exposes selective biases. AppendixC and Figures13–15 document stopping outside a room and confusing beside with past, including an orientation misreading. These support concrete spatial-predicate failure modes, not universal failure of VLM reasoning.\n\nLimitations explicitly exclude long-instruction error correction and editable-scene counterfactuals. Only78 numerical examples, including two fifth and two sixth room cases, give weak coverage of high counts. Verdict: an essential diagnostic baseline and source of controlled contrasts; extending it to long-route, off-path states or persistent uncertainty requires additional validated annotations.',
findings=[{'claim':'NavNuances already uses paired directional commands and Dual SR to diagnose selective bias.','evidence_type':'PAPER EXPERIMENT','source':'NavNuances supplied PDF','locator':'§4.4/Fig6, PDF pp8–9'},{'claim':'Its numerical criterion compares the executed path against competing same-start ordinal routes using nDTW.','evidence_type':'AUTHOR CLAIM','source':'NavNuances supplied PDF','locator':'AppendixB.3, PDF p13'}],
bottlenecks=[{'id':'navnuances-B1','description':'Atomic diagnostics do not cover error recovery in long composed instructions.','conditions':'An agent deviates mid-route, revisits landmarks, or must revise instruction progress after a detour.','cause':'The benchmark intentionally isolates short atomic concepts in fixed scenes.','evidence':'Limitations, PDF p9; only78 ordinal examples in Table1/AppendixD.','kind':'insufficiently tested','followups':'SkillNav explicitly trains skill specialists and evaluates this benchmark; VLN-MME probes broader reasoning, but neither automatically validates off-path composed semantics.','status':'Still unresolved in the reviewed literature','confidence':'High for benchmark scope; bounded to reviewed sources.'},{'id':'navnuances-B2','description':'Metric success can be weaker than full semantic task completion.','conditions':'Moving-towards and walking-past subsets evaluated from endpoint geometry.','cause':'Moving-towards needs only distance reduction; walking-past uses a start–end line rather than every segment of an arbitrary looping path.','evidence':'AppendixB.2, PDF pp12–13. This is a deduction from metric definitions, not an observed score inflation measurement.','kind':'methodological','followups':'Route-fidelity and predicate-state evaluation can complement these diagnostics; revised metrics need validation.','status':'Uncertain because evidence is insufficient','confidence':'High for metric definitions; unknown empirical effect.'}],limits=['No benchmark executed. Figure case captions and text reviewed; screenshots were not independently relabeled. GPT-4 results use a smaller subset than many supervised results.'])
render()
